from typing import List
import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        inf = 10**18
        dist = [inf] * n
        dist[0] = 0
        pq = [(0, 0)]

        while pq:
            cur, node = heapq.heappop(pq)
            if cur != dist[node]:
                continue

            for nxt, w in rev[node]:
                cost = max(cur, w)
                if cost < dist[nxt]:
                    dist[nxt] = cost
                    heapq.heappush(pq, (cost, nxt))

        ans = max(dist)
        return -1 if ans == inf else ans
